create index idx_reservation_item_dates on reservation_item(arrival_date, departure_date);
create index idx_stay_status on stay(organization_id, status);
create index idx_stay_segment_unit_time on stay_segment(unit_id, start_at, end_at);
create index idx_resource_reservation_time on resource_reservation(resource_id, effective_start_at, effective_end_at);
create index idx_turnover_deadline on turnover(property_id, status, ready_deadline);
create index idx_task_due on task(property_id, status, due_at);
create index idx_incident_open on incident(property_id, status, severity);
create index idx_cash_movement_date on cash_movement(organization_id, occurred_at);
create index idx_economic_event_date on economic_event(organization_id, economic_date, status);
create index idx_allocation_event on allocation(economic_event_id);
create index idx_settlement_open on settlement_entry(organization_id, status);
create index idx_outbox_pending on outbox_event(status, available_at) where status in ('PENDING','FAILED_RETRYABLE');
create index idx_dq_open on data_quality_issue(organization_id, status, severity);

